import Foundation
struct User {
    let id: Int
    let name: String
}
struct Post {
    let id: Int
    let userID: Int
    let title: String
}
struct UserProfile {
    let user: User
    let posts: [Post]
}

enum FakeNetwork {
    // Simulates a ~300ms user fetch
    static func fetchUser(id: Int) async throws -> User {
        try await Task.sleep(for: .milliseconds(300))
        return User(id: id, name: "Alice")
    }
    // Simulates a ~500ms posts fetch
    static func fetchPosts(userID: Int) async throws -> [Post] {
        try await Task.sleep(for: .milliseconds(500))
        return [
            Post(id: 1, userID: userID, title: "Understanding Actors"),
            Post(id: 2, userID: userID, title: "async/await in Practice"),
            Post(id: 3, userID: userID, title: "When to Use Task.detached"),
        ]
    }
    // Simulates a ~200ms notification send that can fail
    static func sendNotification(to userID: Int, message: String) async throws {
        try await Task.sleep(for: .milliseconds(200))
        print("  📬 Notification sent to user \(userID): \"\(message)\"")
    }
}

func loadUser(id: Int) async throws -> User {
    print("  → Fetching user \(id)...")
    let user = try await FakeNetwork.fetchUser(id: id)
    print("  ✓ Got user: \(user.name)")
    return user
}

// Sequential: posts don't start until user finishes
func loadProfileSequential(userID: Int) async throws -> UserProfile {
    let start = Date()
    let user  = try await FakeNetwork.fetchUser(id: userID)   // 300ms
    let posts = try await FakeNetwork.fetchPosts(userID: userID) // 500ms
    let elapsed = Date().timeIntervalSince(start)
    print("  Sequential finished in \(String(format: "%.2f", elapsed))s") // ~0.80s
    return UserProfile(user: user, posts: posts)
}

// Parallel: both requests are in-flight at the same time
func loadProfileParallel(userID: Int) async throws -> UserProfile {
    let start = Date()
    async let user  = FakeNetwork.fetchUser(id: userID)      // starts immediately
    async let posts = FakeNetwork.fetchPosts(userID: userID) // also starts immediately
    let (resolvedUser, resolvedPosts) = try await (user, posts)
    let elapsed = Date().timeIntervalSince(start)
    print("  Parallel finished in \(String(format: "%.2f", elapsed))s") // ~0.50s
    return UserProfile(user: resolvedUser, posts: resolvedPosts)
}

// Synchronous context can't use await directly here
func startLoading() {
    Task {
        // Now we're in an async context
        let profile = try await loadProfileParallel(userID: 1)
        print("  Loaded \(profile.posts.count) posts for \(profile.user.name)")
    }
}

Task(priority: .userInitiated) {
    // User tapped something, do it fast
    _ = try await loadProfileParallel(userID: 1)
}
Task(priority: .background) {
    // Housekeeping: run whenever there's capacity
    try await FakeNetwork.sendNotification(to: 1, message: "Sync complete")
}

var currentTask: Task<Void, Never>?
func startNewSearch() {
    // Cancel the previous search before starting a fresh one
    currentTask?.cancel()
    currentTask = Task {
        do {
            let profile = try await loadProfileParallel(userID: 1)
            print("  Search complete: \(profile.user.name)")
        } catch is CancellationError {
            print("  Search was cancelled, that's fine")
        } catch {
            print("  Search failed: \(error)")
        }
    }
}

func processPosts(_ posts: [Post]) async throws {
    for post in posts {
        // Throws CancellationError if the task has been cancelled
        try Task.checkCancellation()
        // Simulate some processing work per post
        try await Task.sleep(for: .milliseconds(100))
        print("  Processed: \"\(post.title)\"")
    }
}

// Regular Task: inherits the caller's actor context and priority
Task {
    try await FakeNetwork.sendNotification(to: 1, message: "Welcome!")
}
// Detached Task: no inherited context, explicit priority, lifecycle is yours to manage
Task.detached(priority: .background) {
    // Runs on the cooperative thread pool regardless of where this line appears
    try? await FakeNetwork.sendNotification(to: 1, message: "Background sync done")
}

func fetchAllProfiles(userIDs: [Int]) async throws -> [UserProfile] {
    try await withThrowingTaskGroup(of: UserProfile.self) { group in
        for id in userIDs {
            group.addTask {
                let user  = try await FakeNetwork.fetchUser(id: id)
                let posts = try await FakeNetwork.fetchPosts(userID: id)
                return UserProfile(user: user, posts: posts)
            }
        }
        // Collect results as each task finishes, order is not guaranteed
        var profiles: [UserProfile] = []
        for try await profile in group {
            profiles.append(profile)
        }
        return profiles
    }
}

import Foundation
import PlaygroundSupport

PlaygroundPage.current.needsIndefiniteExecution = true

// MARK: Models

struct User {
    let id: Int
    let name: String
}

struct Post {
    let id: Int
    let userID: Int
    let title: String
}

struct UserProfile {
    let user: User
    let posts: [Post]
}

// MARK: Fake Network

enum FakeNetwork {

    static func fetchUser(id: Int) async throws -> User {
        try await Task.sleep(for: .milliseconds(300))
        return User(id: id, name: "User \(id)")
    }

    static func fetchPosts(userID: Int) async throws -> [Post] {
        try await Task.sleep(for: .milliseconds(500))
        return [
            Post(id: userID * 10 + 1, userID: userID, title: "Understanding Actors"),
            Post(id: userID * 10 + 2, userID: userID, title: "async/await in Practice"),
            Post(id: userID * 10 + 3, userID: userID, title: "When to Use Task.detached"),
        ]
    }

    static func sendNotification(to userID: Int, message: String) async throws {
        try await Task.sleep(for: .milliseconds(200))
        print("  📬 Notification sent to user \(userID): \"\(message)\"")
    }
}

// MARK: Sequential vs Parallel

func loadProfileSequential(userID: Int) async throws -> UserProfile {
    let start = Date()
    let user  = try await FakeNetwork.fetchUser(id: userID)
    let posts = try await FakeNetwork.fetchPosts(userID: userID)
    let elapsed = Date().timeIntervalSince(start)
    print("  Sequential: \(String(format: "%.2f", elapsed))s")
    return UserProfile(user: user, posts: posts)
}

func loadProfileParallel(userID: Int) async throws -> UserProfile {
    let start = Date()
    async let user  = FakeNetwork.fetchUser(id: userID)
    async let posts = FakeNetwork.fetchPosts(userID: userID)
    let (resolvedUser, resolvedPosts) = try await (user, posts)
    let elapsed = Date().timeIntervalSince(start)
    print("  Parallel:   \(String(format: "%.2f", elapsed))s")
    return UserProfile(user: resolvedUser, posts: resolvedPosts)
}

// MARK: Cancellation

func processPosts(_ posts: [Post]) async throws {
    for post in posts {
        try Task.checkCancellation()
        try await Task.sleep(for: .milliseconds(100))
        print("  ✓ Processed: \"\(post.title)\"")
    }
}

// MARK: Task Group

func fetchAllProfiles(userIDs: [Int]) async throws -> [UserProfile] {
    try await withThrowingTaskGroup(of: UserProfile.self) { group in
        for id in userIDs {
            group.addTask {
                let user  = try await FakeNetwork.fetchUser(id: id)
                let posts = try await FakeNetwork.fetchPosts(userID: id)
                return UserProfile(user: user, posts: posts)
            }
        }
        var profiles: [UserProfile] = []
        for try await profile in group {
            profiles.append(profile)
        }
        return profiles
    }
}

// MARK: Entry Point

Task {

    // ── 1. Sequential vs Parallel ──────────────────────────────────────────
    print("=== Sequential vs Parallel ===")
    _ = try await loadProfileSequential(userID: 1)
    _ = try await loadProfileParallel(userID: 1)

    // 2. Task priority
    print("\n=== Task Priority ===")
    Task(priority: .userInitiated) {
        print("  [userInitiated] fetching user...")
        _ = try await FakeNetwork.fetchUser(id: 99)
        print("  [userInitiated] done")
    }
    Task(priority: .background) {
        print("  [background] sending notification...")
        try await FakeNetwork.sendNotification(to: 99, message: "Hello!")
    }

    // Small pause so the above tasks print before we move on
    try await Task.sleep(for: .milliseconds(600))

    // 3. Cancellation
    print("\n=== Cancellation ===")
    let posts = try await FakeNetwork.fetchPosts(userID: 1)

    let processingTask = Task {
        do {
            try await processPosts(posts)
        } catch is CancellationError {
            print("  ⛔ Processing cancelled mid-way")
        }
    }

    // Cancel after 250ms, should interrupt after ~2 posts processed
    try await Task.sleep(for: .milliseconds(250))
    processingTask.cancel()

    // Wait for the cancelled task to fully wind down
    try await Task.sleep(for: .milliseconds(200))

    // 4. Task.detached
    print("\n=== Task.detached ===")
    Task.detached(priority: .background) {
        print("  [detached] running independently...")
        try? await FakeNetwork.sendNotification(to: 1, message: "Detached sync done")
    }

    // Wait a moment for the detached task to complete
    try await Task.sleep(for: .milliseconds(400))

    // 5. withTaskGroup
    print("\n=== withTaskGroup (3 profiles in parallel) ===")
    let start = Date()
    let profiles = try await fetchAllProfiles(userIDs: [1, 2, 3])
    let elapsed = Date().timeIntervalSince(start)

    for profile in profiles {
        print("  \(profile.user.name): \(profile.posts.count) posts")
    }
    // All 3 fetched concurrently, takes ~500ms instead of ~2400ms
    print("  Finished in \(String(format: "%.2f", elapsed))s (vs ~2.40s sequential)")

    print("\n✅ All done")
    PlaygroundPage.current.finishExecution()
}
